create table if not exists users (id text primary key,email text not null unique,password_hash text not null,name text not null,phone text,role text not null check (role in ('customer','owner')),created_at text not null,updated_at text not null);
create table if not exists password_resets (id text primary key,user_id text not null references users(id) on delete cascade,token text not null,created_at text not null,used integer not null default 0);
create table if not exists addresses (id text primary key,user_id text not null references users(id) on delete cascade,label text not null,address text not null,city text not null,is_default integer not null default 0,created_at text not null,updated_at text not null);
create table if not exists products (id text primary key,sku text not null unique,name text not null,category text not null,category_slug text not null,brand text not null,description text,price real not null default 0,discount real not null default 0,stock integer not null default 0,status text not null default 'active' check (status in ('active','hidden','draft')),created_at text not null,updated_at text not null);
create index if not exists idx_products_search on products(status,category_slug,brand,price,stock);
create table if not exists product_images (id text primary key,product_id text not null references products(id) on delete cascade,url text not null,alt_text text,sort_order integer not null default 0,created_at text not null);
create table if not exists coupons (code text primary key,kind text not null check (kind in ('percent','fixed')),value real not null,min_total real not null default 0,active integer not null default 1,created_at text not null);
create table if not exists cart_items (cart_key text not null,product_id text not null references products(id) on delete cascade,quantity integer not null check(quantity >= 0),updated_at text not null,primary key (cart_key,product_id));
create table if not exists orders (id text primary key,user_id text references users(id),customer_name text not null,phone text not null,email text,address text not null,payment_method text not null,payment_status text not null,order_status text not null check (order_status in ('pending','processing','completed','cancelled')),subtotal real not null,discount real not null default 0,shipping real not null default 0,total real not null,coupon_code text,created_at text not null,updated_at text not null);
create index if not exists idx_orders_status_created on orders(order_status,created_at);
create table if not exists order_items (id text primary key,order_id text not null references orders(id) on delete cascade,product_id text references products(id),sku text,name text not null,quantity integer not null,unit_price real not null,line_total real not null);
create table if not exists notifications (id text primary key,audience text not null,type text not null,message text not null,entity_id text,created_at text not null,read_at text);
